pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;
    function setUp() public { c = new C(); admin = address(this); }

    // Fuzzed param: newOwner candidate
    function testFuzz_property(address newOwner) public {
        // general admissible domain: newOwner can be any address but non-zero to be meaningful
        vm.assume(newOwner != address(0));

        // The reference contract's rule: only the admin (deployer) can call setOwner successfully
        // Deploy-time admin is this test contract (setUp used new C()). We act as admin to invoke setOwner.
        bool ok;
        // call as admin (this contract)
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: when the admin calls setOwner, the public owner getter must equal the supplied newOwner
        // (reference satisfies for all inputs; the mutant that additionally requires msg.sender==owner will
        // prevent this when the admin is not equal to current owner, so the single assert will fail for some fuzz input)
        assertTrue(ok && c.owner() == newOwner);
    }
}

