import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: caller (actor) and the candidate new owner
    function testFuzz_property(address actor, address newOwner) public {
        // Wide admissible domain: ensure actor is not the zero address to make pranks meaningful
        vm.assume(actor != address(0));
        // Ensure newOwner is a valid address (can be zero too, allow it)

        // The reference contract sets owner only if caller is admin. By construction, admin is the deployer (this test contract).
        // We will have the admin (this contract) call setOwner(newOwner) and assert that owner()==newOwner afterwards.
        // The mutant that requires msg.sender==owner will break when admin != owner (which is common), causing owner to not update.

        // perform the call as the admin (the deploying address of c is this test contract)
        // No vm.prank needed because this contract is the deployer/admin
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the admin call completes (whether it reverted or not), the specification for the reference
        // contract is: the public owner() getter must equal newOwner (the admin can always set owner).
        // The mutant may revert or leave owner unchanged when it improperly requires msg.sender==owner.
        assertTrue(c.owner() == newOwner);
    }
}

