pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor who will call (caller) and the address to set as new owner (newOwner)
    function testFuzz_property(address caller, address newOwner) public {
        // Keep wide domain but avoid the zero-address for clarity (owner may be set to zero in principle,
        // but requiring non-zero reduces meaningless duplicates while staying wide).
        // Allow caller to be any address including the deployer (admin) or others.
        if (address(0) == caller) caller = address(1);
        // Ensure newOwner is a normal non-zero address to make change observable
        if (address(0) == newOwner) newOwner = address(2);

        // The contract's admin is the deployer (this test contract). We'll impersonate that admin to call setOwner.
        // The property: when admin calls setOwner(newOwner), the public owner() getter should equal newOwner after the call.
        vm.prank(address(this)); // deployer/admin calls
        bool ok;
        try c.setOwner(newOwner) returns (bool success) { ok = success; } catch { ok = false; }

        // Exactly one assertion: the reference implementation always results in owner() == newOwner after admin call;
        // the mutant (which additionally requires msg.sender==owner) will fail this when admin != owner for some inputs,
        // producing a counterexample the fuzzer can find.
        assertTrue(c.owner() == newOwner);
    }
}

