        vm.assume(newOwner != address(0));

        // admin is the deployer (address(this) in setUp created c), so we must act as that admin
        // The deployer of c was this test contract, so msg.sender must be this contract when calling.
        // Call setOwner as admin and observe owner getter.
        bool ok;
        try c.setOwner(newOwner) returns (bool) { ok = true; } catch { ok = false; }

        // The reference contract always allows the admin (deployer) to set owner to newOwner,
