pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address (could be admin, owner, or any other EOA)
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses non-zero to be meaningful
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // capture initial admin and owner: admin is deployer (this contract in setUp), owner is deployer
        address admin = address(this);

        // Ensure the fuzzer explores both cases where caller == admin and caller == owner
        // but do not constrain; we only assume non-zero above.

        // Attempt to call setOwner as the fuzzed caller and record whether the call succeeded
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: ONLY the admin can successfully call setOwner. That means
        // for any caller, success iff caller == admin. We assert the reference satisfies
        // that: ok == (caller == admin).
        // This will pass on the reference implementation for all inputs, and fail on the mutant
        // which also allows owner to succeed when caller == owner (i.e., when caller != admin but caller == owner).
        assertTrue(ok == (caller == admin));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: caller address candidate
    function testFuzz_property(address caller) public {
        // Keep domain wide but avoid the zero address which is unlikely meaningful here
        vm.assume(caller != address(0));

        // The reference contract ensures: only the original deployer (admin) can change owner.
        // We will check that when someone who is NOT the admin calls setOwner, the owner does NOT become that caller.
        // This distinguishes the mutant which permits current owner to call as well.

        // Determine admin (deployer) and current owner (initially deployer). Both are the test contract's address when setUp ran.
        address admin = address(this); // because setUp used new C() from this test contract

        // If caller is admin, they are allowed to set owner; the property only requires protection for non-admin callers.
        if (caller == admin) {
            // skip the trivial allowed case; still satisfy universal quantification by returning early
            return;
        }

        // Ensure caller has some ether so calls are possible if needed
        vm.deal(caller, 1 ether);

        // Caller attempts to set owner to themselves
        vm.prank(caller);
        bool ok;
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call (whether reverted or not), the reference C must not have owner == caller when caller != admin.
        // So we assert that owner() != caller.
        // This will hold for the reference for ALL inputs; the mutant (which allows owner to call) can violate it when
        // caller equals current owner (which initially equals admin) — to catch that case, we ensured we did not skip only-admin,
        // and because owner may change in other flows in mutated contract, the fuzzer can find a sequence where caller != admin but caller == owner
        // Here we check the public getter owner() exactly once as required.
        assertTrue(c.owner() != caller);
    }
}
